def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out."""
    # Find the longest common prefix
    prefix_len = 0
    for i in range(min(len(s_in), len(s_out))):
        if s_in[i] == s_out[i]:
            prefix_len += 1
        else:
            break

    # Find the longest common suffix
    suffix_len = 0
    for i in range(1, min(len(s_in), len(s_out)) + 1):
        if s_in[-i] == s_out[-i]:
            suffix_len += 1
        else:
            break

    # Determine what needs to be replaced
    if len(s_in) > len(s_out):
        # Deletion occurred
        old_sub = s_in[prefix_len:len(s_in)-suffix_len]
        new_sub = ""
    elif len(s_in) < len(s_out):
        # Insertion occurred
        old_sub = s_in[prefix_len:len(s_in)-suffix_len] if len(s_in)-suffix_len > prefix_len else ""
        new_sub = s_out[prefix_len:len(s_out)-suffix_len] if len(s_out)-suffix_len > prefix_len else ""
    else:
        # Substitution occurred
        old_sub = s_in[prefix_len:len(s_in)-suffix_len] if len(s_in)-suffix_len > prefix_len else ""
        new_sub = s_out[prefix_len:len(s_out)-suffix_len] if len(s_out)-suffix_len > prefix_len else ""

    # Simpler approach - just find what's different
    if len(s_in) == len(s_out):
        # Same length - substitution
        for i in range(len(s_in)):
            if s_in[i] != s_out[i]:
                return (s_in[i], s_out[i], i)
        return (s_in[0], s_out[0], 0)  # fallback
    else:
        # Different lengths - deletion or insertion
        # Let's try to find the substring that needs to be replaced
        if len(s_in) > len(s_out):
            # Deletion
            for i in range(len(s_in)):
                if i >= len(s_out) or s_in[i] != s_out[i]:
                    # Check if removing s_in[i] makes it match
                    if s_in[:i] + s_in[i+1:] == s_out:
                        return (s_in[i], "", i)
                    # Try other positions
                    break
        else:
            # Insertion
            for i in range(len(s_out)):
                if i >= len(s_in) or s_in[i] != s_out[i]:
                    # Check if inserting s_out[i] at position i makes it match
                    if s_in[:i] + s_out[i] + s_in[i:] == s_out:
                        return ("", s_out[i], i)
                    # Try other positions
                    break
        # Fallback for complex cases
        return (s_in, s_out, 0)

