                if j >= len(outp) or inp[j] != outp[j]:
                    print(f"  Character at position {j} ('{inp[j]}') was deleted")
                    break
        elif len(inp) < len(outp):
            # Something was inserted  
            print(f"  Inserted: {len(outp) - len(inp)} character(s)")
