def propose_rule_candidates(s_in, s_out):
    """Generate candidate replacement rules from a transformation."""
    candidates = []

    # For deletion case (when output is shorter)
    if len(s_in) > len(s_out):
        # Find what was deleted
        for i in range(len(s_in)):
            if i >= len(s_out) or s_in[i] != s_out[i]:
                # Try deleting this character
                pattern = s_in[i]
                replacement = ""
                candidates.append((pattern, replacement))
                break

    # For substitution case (same length)
    elif len(s_in) == len(s_out):
        for i in range(len(s_in)):
            if s_in[i] != s_out[i]:
                # Try replacing this character
                pattern = s_in[i]
                replacement = s_out[i]
                candidates.append((pattern, replacement))
                break

    # For insertion case (when output is longer)
    elif len(s_in) < len(s_out):
        # Find what was inserted
        for i in range(len(s_out)):
            if i >= len(s_in) or s_in[i] != s_out[i]:
                # Try inserting this character at this position
                pattern = ""  # We're inserting
                replacement = s_out[i]
                candidates.append((pattern, replacement))
                break

    # Also add general patterns (longer substrings)
    # Try patterns of length 2 and 3 if possible
    if len(s_in) >= 2:
        pattern = s_in[:2]
        if len(s_out) >= 2:
            replacement = s_out[:2]
            candidates.append((pattern, replacement))

    if len(s_in) >= 3:
        pattern = s_in[:3]
        if len(s_out) >= 3:
            replacement = s_out[:3]
            candidates.append((pattern, replacement))

    # Add reverse patterns too
    if len(s_in) >= 2:
        pattern = s_in[-2:]
        if len(s_out) >= 2:
            replacement = s_out[-2:]
            candidates.append((pattern, replacement))

    if len(s_in) >= 3:
        pattern = s_in[-3:]
        if len(s_out) >= 3:
            replacement = s_out[-3:]
            candidates.append((pattern, replacement))

    return candidates

